  "claude-science.empty": "Аккаунтов пока нет. Каждый аккаунт — отдельный Claude Science на хосте (свой каталог и вход), запускаемый cutex.",
  "claude-science.hideLogs": "Скрыть журналы",
  "claude-science.removeConfirm": "Удалить аккаунт {name}? Его Claude Science остановится и будет снят с регистрации в cutex. Каталог аккаунта {home} останется и не будет удалён; добавьте его снова с тем же каталогом, чтобы продолжить с того же места.",
