  "claude-science.form.title": "Добавление аккаунта Claude Science",
  "claude-science.form.idHint": "Строчные буквы, цифры и -, до 12; служба называется claude-science-<ID>",
  "claude-science.form.home": "Каталог аккаунта (на хосте)",
  "claude-science.form.homeHint": "HOME аккаунта, создаётся при отсутствии. Существующий каталог сохранит уже выполненный вход (сначала остановите этот аккаунт везде, где он работает). Не более 41 символа (ограничение Claude Science). Удаление аккаунта никогда его не удаляет.",
