  "claude-science.otherHost": "Аккаунты этого хоста открываются во вкладке его браузера: сначала откройте одного из {{agents}} этого хоста, затем снова нажмите «Открыть»",
  "claude-science.login.title": "Первый вход",
  "claude-science.login.step1": "Нажмите «Открыть»: встроенный браузер открывает аккаунт на локальной странице входа Claude Science (одноразовая ссылка, создаётся заново при каждом открытии). Нажмите Sign in.",
  "claude-science.login.step2": "Внутри нажмите Sign in on the web и войдите в этот аккаунт на claude.ai. Если claude.ai показывает другой аккаунт, сначала переключитесь или выйдите; этот шаг можно выполнить и в другом браузере, где выполнен вход в этот аккаунт.",
